  `brake_type` varchar(50) NOT NULL,
  `railway_division` varchar(100) NOT NULL,
  `shed_name` varchar(100) NOT NULL,
  `inspection_date` date NOT NULL,
  `observation_text` varchar(255) DEFAULT NULL,
  `remarks` text NOT NULL,
